llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Desvenlafaxine has an absolute oral bioavailability of 80.5% in humans after a single oral dose versus IV, demonstrating high F for a phenolic cyclohexane drug; structural transferability to the query is limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Estetrol is reported to have high and dose-related oral bioavailability in humans, but the record is qualitative and the steroid scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin shows high oral bioavailability in egg yolk, attributed to dietary fat; the conjugated polyene motif is somewhat similar, but the evidence is qualitative and formulation-dependent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Meperidine/pethidine has an absolute oral bioavailability of 61% in healthy volunteers, supporting high F, though the small basic ester scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Apatinib shows good oral bioavailability in humans, but the record is qualitative and the kinase-inhibitor scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Proguanil has an absolute oral bioavailability as high as 60% in humans, supporting high F, though the biguanide scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cortisone has an oral bioavailability of 85% in subjects, supporting high F, though the rigid steroid scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Leflunomide has an oral bioavailability as high as 80% in humans, supporting high F; the amide and trifluoromethylphenyl motifs are moderately analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide has an absolute oral bioavailability approaching 100% in fasted healthy subjects, strongly supporting high F; the amide and trifluoromethylphenyl motifs are moderately analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Aminoglutethimide has an oral bioavailability of ≈100% in patients, supporting high F, though the imide scaffold is not closely analogous to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All experimental evidence points to oral bioavailability at or above the F≥20% threshold, with many analogs showing high (60–100%) F. No affirmative evidence for low F was found. The most transferable evidence comes from amide-containing drugs with near-complete absorption, supporting a high bioavailability prediction for the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "The impact of the long conjugated polyene chain on solubility, permeability, and metabolic stability is not directly addressed by the available records.",
    "Most supporting records are from structurally distant scaffolds, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

